from src.nodes.base import BaseNode
import os

_IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".tiff", ".tif", ".webp", ".exr", ".hdr"}

class List_Images_RecursiveNode(BaseNode):
    name = "list_images_recursive"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("folder_path", "string", widget_type="text")
        self.add_input("recursive", "bool", widget_type="bool", default=False)
        self.add_output("image_paths", "list")
        self.add_output("count", "int")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        folder_path = inputs.get("folder_path", "")
        recursive = inputs.get("recursive", False)

        if not folder_path or not os.path.isdir(folder_path):
            self.log_error(f"Invalid folder path: {folder_path!r}")
            return {"image_paths": [], "count": 0, "exec_out": True}

        paths = []
        if recursive:
            for root, _, files in os.walk(folder_path):
                for fname in sorted(files):
                    if os.path.splitext(fname)[1].lower() in _IMAGE_EXTS:
                        paths.append(os.path.join(root, fname))
        else:
            for fname in sorted(os.listdir(folder_path)):
                if os.path.splitext(fname)[1].lower() in _IMAGE_EXTS:
                    full = os.path.join(folder_path, fname)
                    if os.path.isfile(full):
                        paths.append(full)

        return {"image_paths": paths, "count": len(paths), "exec_out": True}

def register_node():
    return List_Images_RecursiveNode
